// /tg/poll bridge : {ok,count,messages:[{message_id|id,date,from,thread,text,type,reply_to}]} - deja dedupes + mutex
// Intentions deterministes -> Hub direct (pas de LLM = pas d'hallucination sur donnees live).
const msgs = $json.messages || [];
const out = [];
const cmdRe = new RegExp('^' + String.fromCharCode(92) + '/(' + String.fromCharCode(92) + 'w+)(@' + String.fromCharCode(92) + 'w+)?' + String.fromCharCode(92) + 's*(.*)$');
const botRe = /moi_hermes_bot|herm[eèéês]s/i;
const ADMIN_IDS = new Set([630047399]); // Ibn lascard - admin du canal
const isAdmin = (m) => ADMIN_IDS.has(Number(m.from_id)||0) || /lascard/i.test(String(m.from||''));
const INTENTS = [
  [/(^|[^é])epingle|epingler|pin( |$|ça|ca )/i, (m) => (m.reply_to&&(m.reply_to.message_id||m.reply_to)) ? { mode:'hub', action:'pin', messageId: (m.reply_to.message_id||m.reply_to) } : { mode:'send', text:'Reponds au message a epingler avec : epingle ca' }],
  [/retire.{0,10}(epingle|pin)|desepingle|unpin/i, (m) => (m.reply_to&&(m.reply_to.message_id||m.reply_to)) ? { mode:'hub', action:'unpin', messageId: (m.reply_to.message_id||m.reply_to) } : { mode:'send', text:'Reponds au message a desepingler avec : desepingle ca' }],
  [/supprime.{0,15}message|efface.{0,15}message|delete/i, (m) => (m.reply_to&&(m.reply_to.message_id||m.reply_to)) ? { mode:'hub', action:'delete', messageId: (m.reply_to.message_id||m.reply_to) } : { mode:'send', text:'Reponds au message a supprimer avec : supprime ca' }],
  [/admins?|administrateurs?/i, () => ({ mode:'hub', action:'admins' })],
  [/statistiques?|stats?|combien de membres|nombre de membres/i, () => ({ mode:'hub', action:'stats' })],
  [/sujets?|topics? du forum|liste des topics?/i, () => ({ mode:'hub', action:'topics' })],
  [/membres?|participants?|qui est dans le (groupe|chat|caverne)|qui fait partie/i, () => ({ mode:'hub', action:'members' })],
  [/derniers? messages?|messages? recents?|historique du (groupe|chat)/i, () => ({ mode:'hub', action:'history', limit: 5 })],
  [/infos? du (groupe|chat|caverne)|chat ?info/i, () => ({ mode:'hub', action:'chat' })],
];
for (const m of msgs) {
  if (!m.text || m.type !== 'text') continue;
  if (botRe.test(m.from || '')) continue;
  const t = String(m.text);
  const base = { chat: 'caverne', messageId: m.message_id || m.id, thread: m.thread || null, from: m.from || '', fromId: m.from_id || 0 };
  const cm = cmdRe.exec(t);
  if (cm && cm[2] && !/moi_hermes_bot/i.test(cm[2])) continue;
  if (cm) {
    const c = cm[1].toLowerCase(), arg = (cm[3] || '').trim();
    if (c === 'aide' || c === 'help' || c === 'start') { out.push({ json: { ...base, mode: 'send', text: '/aide /status /poll /membres /admins /stats /topics + questions libres + actions en langage naturel (epingle ca, liste les membres...). Hermes via OmniRoute/free.' } }); continue; }
    if (c === 'status') { out.push({ json: { ...base, mode: 'send', text: 'Hermes actif : agent n8n via OmniRoute + outils MCP (memoire, beacon, actions telegram). Fallback chaine provider_prefs.' } }); continue; }
    if (c === 'poll') { const parts = arg.split('|').map((s) => s.trim()).filter(Boolean); if (parts.length >= 3) { out.push({ json: { ...base, mode: 'hub', action: 'poll', question: parts[0], options: parts.slice(1) } }); continue; } out.push({ json: { ...base, mode: 'send', text: 'Usage : /poll Question | option1 | option2 [| option3...]' } }); continue; }
    if (['membres','admins','stats','topics'].includes(c)) { const act = { membres: 'members', admins: 'admins', stats: 'stats', topics: 'topics' }[c]; out.push({ json: { ...base, mode: 'hub', action: act } }); continue; }
    out.push({ json: { ...base, mode: 'send', text: 'Commande inconnue - /aide pour la liste.' } }); continue;
  }
  let hit = null;
  for (const [re, fn] of INTENTS) { if (re.test(t)) { hit = fn(m); break; } }
  if (hit) {
    if (['pin','unpin','delete'].includes(hit.action) && !isAdmin(m)) hit = { mode:'send', text:'Action reservee a l admin du canal (Ibn lascard).' };
    out.push({ json: { ...base, ...hit } }); continue;
  }
  out.push({ json: { ...base, mode: 'llm', prompt: t, from: m.from || 'membre' } });
}
return out;

