const m = $json;
if (m.mode === 'hub' && m.hub) { return [{ json: { mode: 'send', chat: m.chat, messageId: m.messageId, thread: m.thread, text: String(m.hub.stdout || JSON.stringify(m.hub)).slice(0, 1500) } }]; }
return [{ json: m }];
